/**
 * Read SDK screens (`screen('Checkout', { placeOrder: { role: 'button', name: 'Place order' } })`)
 * from TypeScript source WITHOUT running it: the TypeScript compiler API
 * parses the module and only literal values (strings, numbers, booleans,
 * arrays and object literals) are read. Function entries (`row: (id) => ...`)
 * and computed values are skipped and reported. This is how screen modules
 * written by hand or generated by an importer plugin join the element repository.
 */
import type * as TS from 'typescript';
import { loadTypeScript } from '../importers/typescript.js';
import { specToTarget, type ElementSpec } from '../sdk/screen.js';
import { elementFromEntry, screenId, type RepoElement, type RepositoryProblem } from './repository.js';

class NotLiteral extends Error {}

function literalOf(ts: typeof TS, n: TS.Expression): unknown {
  if (ts.isStringLiteral(n) || ts.isNoSubstitutionTemplateLiteral(n)) return n.text;
  if (ts.isNumericLiteral(n)) return Number(n.text);
  if (n.kind === ts.SyntaxKind.TrueKeyword) return true;
  if (n.kind === ts.SyntaxKind.FalseKeyword) return false;
  if (ts.isArrayLiteralExpression(n)) return n.elements.map((e) => literalOf(ts, e as TS.Expression));
  if (ts.isObjectLiteralExpression(n)) {
    const o: Record<string, unknown> = {};
    for (const p of n.properties) {
      if (!ts.isPropertyAssignment(p) || !(ts.isIdentifier(p.name) || ts.isStringLiteral(p.name))) throw new NotLiteral();
      o[p.name.text] = literalOf(ts, p.initializer);
    }
    return o;
  }
  if (ts.isAsExpression(n) || ts.isParenthesizedExpression(n) || ts.isSatisfiesExpression?.(n)) return literalOf(ts, (n as TS.AsExpression).expression);
  throw new NotLiteral();
}

/** Elements of every `screen(name, {...})` call in a module. */
export async function readScreenModule(text: string, file: string): Promise<{ elements: RepoElement[]; problems: RepositoryProblem[] }> {
  const ts = await loadTypeScript();
  const sf = ts.createSourceFile(file, text, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS);
  const elements: RepoElement[] = [];
  const problems: RepositoryProblem[] = [];
  const visit = (n: TS.Node) => {
    if (ts.isCallExpression(n) && ts.isIdentifier(n.expression) && n.expression.text === 'screen' && n.arguments.length >= 2) {
      const [nameArg, specArg] = n.arguments;
      if ((ts.isStringLiteral(nameArg) || ts.isNoSubstitutionTemplateLiteral(nameArg)) && ts.isObjectLiteralExpression(specArg)) {
        const screen = nameArg.text;
        for (const p of specArg.properties) {
          if (!ts.isPropertyAssignment(p) || !(ts.isIdentifier(p.name) || ts.isStringLiteral(p.name))) continue;
          const key = p.name.text;
          const line = sf.getLineAndCharacterOfPosition(p.getStart(sf)).line + 1;
          let v: unknown;
          try {
            v = literalOf(ts, p.initializer);
          } catch {
            problems.push({ file, message: `${screenId(screen)}.${key} (line ${line}) is computed or a function; it stays in code only` });
            continue;
          }
          try {
            if (typeof v === 'string') elements.push(elementFromEntry(screen, key, v, file, line, 'screen'));
            else {
              const t = specToTarget(v as ElementSpec, `${key} (${screen})`);
              elements.push({
                id: `${screenId(screen)}.${key}`, screen, key, description: t.description, locators: t.locators, aliases: [], file, line, source: 'screen',
                ...(t.frames?.length ? { frames: t.frames } : {}),
              });
            }
          } catch (e) {
            problems.push({ file, message: `${screenId(screen)}.${key} (line ${line}): ${(e as Error).message}` });
          }
        }
      }
    }
    ts.forEachChild(n, visit);
  };
  visit(sf);
  return { elements, problems };
}
